// Classify messages for appropriate channel routing
const payload = msg.payload;
const sourceBot = msg.sourceBot || 'unknown';

// Determine message type and priority
let messageType = 'app'; // default
let priority = 'normal';

if (payload.type === 'error' || payload.type === 'alert') {
    messageType = 'sys';
    priority = 'high';
} else if (payload.type === 'notification' || payload.type === 'user_action') {
    messageType = 'ui';
    priority = 'medium';
} else if (payload.type === 'state_change' || payload.type === 'deployment') {
    messageType = 'app';
    priority = payload.type === 'deployment' ? 'high' : 'normal';
}

msg.classification = {
    messageType: messageType,
    priority: priority,
    sourceBot: sourceBot,
    timestamp: new Date().toISOString(),
    messageId: Math.random().toString(36).substr(2, 9)
};

return msg;

// Collect comprehensive system analytics
const analytics = context.get('systemAnalytics') || {
    totalMessages: 0,
    channelStats: { app: 0, sys: 0, ui: 0 },
    botStats: {},
    errorCount: 0,
    alertCount: 0,
    performanceMetrics: {
        avgResponseTime: 0,
        peakLoad: 0,
        uptime: 100
    },
    lastUpdate: new Date().toISOString()
};

// Update message statistics
analyticsมessageCount++;
const channel = msg.classification?.messageType || 'unknown';
if (analytics.channelStats[channel] !== undefined) {
    analytics.channelStats[channel]++;
}

// Update bot statistics
const sourceBot = msg.classification?.sourceBot || 'unknown';
if (!analytics.botStats[sourceBot]) {
    analytics.botStats[sourceBot] = {
        messageCount: 0,
        lastSeen: null,
        errorCount: 0
    };
}
analytics.botStats[sourceBot].messageCount++;
analytics.botStats[sourceBot].lastSeen = new Date().toISOString();

// Track errors
if (msg.payload.type === 'error') {
    analytics.errorCount++;
    analytics.botStats[sourceBot].errorCount++;
}

// Track alerts
if (msg.payload.type === 'alert') {
    analytics.alertCount++;
}

// Calculate performance metrics
const now = Date.now();
const messageTime = new Date(msg.classification?.timestamp || now).getTime();
const responseTime = now - messageTime;
analytics.performanceMetrics.avgResponseTime = 
    (analytics.performanceMetrics.avgResponseTime + responseTime) / 2;

if (responseTime > analytics.performanceMetrics.peakLoad) {
    analytics.performanceMetrics.peakLoad = responseTime;
}

analytics.lastUpdate = new Date().toISOString();
context.set('systemAnalytics', analytics);

msg.analytics = analytics;
return msg;

// Process system alerts and notifications
const payload = msg.payload;
const alerts = context.get('activeAlerts') || [];

if (payload.type === 'alert' || payload.level === 'error') {
    const alert = {
        id: Math.random().toString(36).substr(2, 9),
        type: payload.type || 'system_alert',
        message: payload.message || 'System alert triggered',
        severity: payload.severity || 'medium',
        source: payload.source || 'system',
        timestamp: new Date().toISOString(),
        acknowledged: false
    };

    alerts.push(alert);

    // Keep only last 50 alerts
    if (alerts.length > 50) {
        alerts.splice(0, alerts.length - 50);
    }

    context.set('activeAlerts', alerts);

    // Send urgent alerts to UI channel
    if (alert.severity === 'high') {
        msg.urgentAlert = alert;
        return [msg, msg]; // Send to both outputs
    }
}

msg.alerts = alerts;
return [msg, null];

// Handle urgent alerts requiring immediate attention
const alert = msg.urgentAlert;

if (alert) {
    // Prepare urgent notification for UI
    msg.payload = {
        type: 'urgent_notification',
        alert: alert,
        requiresAcknowledgment: true,
        autoEscalate: true,
        escalationDelay: 300000 // 5 minutes
    };

    // Set high priority
    msg.priority = 'urgent';
    msg.classification = {
        messageType: 'ui',
        priority: 'urgent',
        sourceBot: 'SystemMonitor',
        timestamp: new Date().toISOString()
    };

    return msg;
}

return null;

// Coordinate messages between different rooms
const payload = msg.payload;

if (payload.type === 'cross_room_request') {
    const coordination = {
        sourceRoom: payload.sourceRoom,
        targetRoom: payload.targetRoom,
        messageType: payload.messageType || 'coordination',
        coordinationId: Math.random().toString(36).substr(2, 9),
        timestamp: new Date().toISOString()
    };

    // Route based on coordination rules
    if (payload.sourceRoom === 'development' && payload.targetRoom === 'production') {
        // Development to Production: Deployment coordination
        msg.deploymentCoordination = {
            ...coordination,
            action: 'prepare_deployment',
            requiresApproval: true
        };
    } else if (payload.sourceRoom === 'production' && payload.targetRoom === 'ui-management') {
        // Production to UI: Status updates
        msg.statusCoordination = {
            ...coordination,
            action: 'status_update',
            displayLevel: 'info'
        };
    }

    msg.coordination = coordination;
}

return msg;

// Monitor bot health and performance
const bots = msg.payload.bots || [];
const healthReport = {
    totalBots: bots.length,
    healthyBots: 0,
    unhealthyBots: 0,
    offlineBots: 0,
    performanceIssues: [],
    timestamp: new Date().toISOString()
};

bots.forEach(bot => {
    if (bot.status === 'offline') {
        healthReport.offlineBots++;
    } else if (bot.health && bot.health.status === 'healthy') {
        healthReport.healthyBots++;
    } else {
        healthReport.unhealthyBots++;

        // Check for performance issues
        if (bot.performance) {
            if (bot.performance.responseTime > 1000) {
                healthReport.performanceIssues.push({
                    bot: bot.name,
                    issue: 'high_response_time',
                    value: bot.performance.responseTime
                });
            }
            if (bot.performance.memoryUsage > 80) {
                healthReport.performanceIssues.push({
                    bot: bot.name,
                    issue: 'high_memory_usage',
                    value: bot.performance.memoryUsage
                });
            }
        }
    }
});

// Generate alerts for unhealthy bots
if (healthReport.unhealthyBots > 0) {
    msg.healthAlert = {
        type: 'bot_health_alert',
        severity: healthReport.unhealthyBots > 2 ? 'high' : 'medium',
        message: `${healthReport.unhealthyBots} bot(s) reporting health issues`,
        details: healthReport
    };
}

msg.healthReport = healthReport;
return msg;
